import { apiFetch, API_BASE_URL } from "./apiClient";

// Local private variable to store the short-lived JWT safely in application memory
let _accessToken = null;

export async function login(username, password, turnstileToken) {
    try {
        const response = await apiFetch(`${API_BASE_URL}/Auth/login`, {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            body: JSON.stringify({ 
                username, 
                password,
                captchaToken: turnstileToken 
            }),
            credentials: "include" 
        });

        const data = await response.json();

        if (response.ok && data.accessToken) {
            _accessToken = data.accessToken; 
            localStorage.setItem("accessToken", data.accessToken); // 💾 Save to storage for hard reloads
        }

        return {
            success: response.ok,
            status: response.status,
            data
        };
    } catch (error) {
        console.error("Auth HTTP Error:", error);
        return {
            success: false,
            status: 500,
            data: { message: "Cannot reach the authorization server." }
        };
    }
}

export function getAccessToken() {
    return _accessToken;
}

export async function logout() {
    try {
        const response = await apiFetch(`${API_BASE_URL}/Auth/logout`, {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            credentials: "include"
        });

        _accessToken = null; 
        localStorage.removeItem("accessToken"); // 🧹 Clear storage on logout
        console.log("In-memory and stored JWT cleared.");
        
        return response.ok; 
        
    } catch (error) {
        console.error("Logout Error:", error);
        // Clear local tokens even if the network call fails
        _accessToken = null;
        localStorage.removeItem("accessToken");
        return false;
    }
}

// Manual or Interceptor based silent refresh agent
export async function serviceTriggerSilentRefresh() {
    try {
        console.log(`Triggering manual POST request to: ${API_BASE_URL}/Auth/refresh`);
        
        const response = await apiFetch(`${API_BASE_URL}/Auth/refresh`, {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            credentials: "include" 
        });

        const data = await response.json();
        console.log("Refresh response status from server:", response.status);

        if (response.ok && data.accessToken) {
            _accessToken = data.accessToken; 
            localStorage.setItem("accessToken", data.accessToken); // 💾 Update storage on fresh token
            return { success: true, token: data.accessToken };
        } else {
            // Clear stale token if refresh fails
            _accessToken = null;
            localStorage.removeItem("accessToken");
            return { success: false, message: data.message || "Failed to parse token." };
        }
    } catch (error) {
        console.error("Network error executing silent refresh:", error);
        return { success: false, message: "Server connection failure" };
    }
}

// Core fetch engine with integrated automated 401 interceptor loop
export async function fetchSecureUsersList() {
    try {
        let token = _accessToken; 

        console.log(`Sending protected request to: ${API_BASE_URL}/User with Bearer Token...`);
        
        let response = await apiFetch(`${API_BASE_URL}/User`, {
            method: "GET",
            headers: {
                "Content-Type": "application/json",
                "Authorization": `Bearer ${token}` 
            }
        });

        // THE INTERCEPTOR LOOP
        if (response.status === 401) {
            console.warn("Token expired (401). Attempting automatic silent refresh...");
            const refreshResult = await serviceTriggerSilentRefresh();

            if (refreshResult.success) {
                console.log("Silent refresh succeeded! Retrying user list request...");
                token = _accessToken; 
                response = await apiFetch(`${API_BASE_URL}/User`, {
                    method: "GET",
                    headers: {
                        "Content-Type": "application/json",
                        "Authorization": `Bearer ${token}` 
                    }
                });
            } else {
                console.error("Refresh token expired too. User must log in again.");
                return { success: false, message: "Session expired. Please log in again." };
            }
        }

        const data = await response.json();
        return { success: true, data };
    } catch (error) {
        console.error("Secure fetch failure:", error);
        return { success: false, message: "Network Error" };
    }
}

